macro.command:
const version = "13.0.65";
const ADV_NAME = "Gloves of Soul Catching: Advantage";
try {
  if (workflow.hitTargets.size === 0) return {};
  const isUnarmed = rolledItem?.system?.identifier === "unarmed-strike"
    || rolledItem?.system?.type?.value === "unarmed"
    || rolledItem?.name === "Unarmed Strike";
  if (!isUnarmed) return {};

  const hp = actor.system.attributes.hp;
  const choice = await foundry.applications.api.DialogV2.wait({
    window: { title: macroItem.name },
    position: { width: 420 },
    content: `<p>Spend the gloves' power for an extra 2d10 force damage?</p>`
      + (hp.value >= hp.max ? `<p><em>You are already at full hit points.</em></p>` : ""),
    buttons: [
      { action: "heal", label: "Regain hit points", default: true },
      { action: "advantage", label: "Advantage on one roll instead" },
      { action: "no", label: "Don't use" }
    ],
    close: () => "no"
  });
  if (choice === "no") return {};

  const roll = await new CONFIG.Dice.DamageRoll("2d10", {}, {
    type: "force", isCritical: workflow.isCritical, flavor: macroItem.name
  }).evaluate();

  if (choice === "heal") {
    // Rolled force damage, not the amount left after the target's resistances. Applied via
    // applyDamage so dnd5e's damage/healing hooks fire and dependent automation can react.
    await actor.applyDamage([{ value: roll.total, type: "healing" }]);
  } else {
    for (const ef of actor.effects.filter(e => e.name === ADV_NAME)) await ef.delete();
    await actor.createEmbeddedDocuments("ActiveEffect", [{
      name: ADV_NAME,
      img: macroItem.img,
      origin: macroItem.uuid,
      duration: { rounds: 1 },
      changes: [{ key: "flags.midi-qol.advantage.all", mode: 5, value: "1", priority: 20 }],
      // Consumed by the first attack, check, save or skill roll; the duration is the backstop.
      flags: { dae: { specialDuration: ["1Attack", "isCheck", "isSave", "isSkill"], stackable: "noneName" } }
    }]);
  }
  return roll;
} catch (err) {
  console.error(`Gloves of Soul Catching ${version}`, err);
  return {};
}
